"""Bulk CSV import endpoint for Flask.

POST /import accepts a multipart file with rows: name,email,age
Validates each row (email format, age integer 0-150), inserts valid
rows into the SQLite users table in a single transaction, and returns
200 {"imported": N, "errors": [{"line": int, "reason": str}, ...]}
with line numbers starting at 2 (header is line 1).
"""

import csv
import io
import re
import sqlite3

from flask import Flask, jsonify, request

app = Flask(__name__)
DATABASE = "users.db"

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT NOT NULL UNIQUE,
            age INTEGER NOT NULL
        )
        """
    )
    return conn


def validate_row(row):
    """Return (clean_row, reason). clean_row is None if invalid."""
    if len(row) != 3:
        return None, "expected 3 columns (name,email,age), got %d" % len(row)

    name, email, age_raw = (field.strip() for field in row)

    if not name:
        return None, "name is empty"
    if not email:
        return None, "email is empty"
    if not EMAIL_RE.match(email):
        return None, "invalid email format"
    try:
        age = int(age_raw)
    except ValueError:
        return None, "age is not an integer"
    if not 0 <= age <= 150:
        return None, "age out of range (0-150)"

    return (name, email, age), None


@app.post("/import")
def import_csv():
    file = request.files.get("file")
    if file is None:
        return jsonify({"error": "missing multipart 'file' field"}), 400

    try:
        text = file.stream.read().decode("utf-8-sig")
    except UnicodeDecodeError:
        return jsonify({"error": "file must be UTF-8 encoded"}), 400

    reader = csv.reader(io.StringIO(text))
    imported = []
    errors = []

    # Header is line 1; data lines start at line 2.
    next(reader, None)
    for lineno, row in enumerate(reader, start=2):
        if not any(field.strip() for field in row):
            continue  # skip blank lines entirely
        clean, reason = validate_row(row)
        if reason is None:
            imported.append(clean)
        else:
            errors.append({"line": lineno, "reason": reason})

    db = get_db()
    try:
        with db:  # single transaction; rolls back on failure
            db.executemany(
                "INSERT INTO users (name, email, age) VALUES (?, ?, ?)",
                imported,
            )
    except sqlite3.IntegrityError as exc:
        db.close()
        # Duplicate email inside the batch or vs. existing rows.
        email = str(exc).split(": ")[-1] if ": " in str(exc) else ""
        msg = f"duplicate email{f': {email}' if email else ''}"
        return (
            jsonify({"error": f"import aborted: {msg}", "imported": 0}),
            409,
        )
    db.close()

    return jsonify({"imported": len(imported), "errors": errors}), 200


@app.get("/users")
def list_users():
    db = get_db()
    rows = db.execute("SELECT id, name, email, age FROM users ORDER BY id").fetchall()
    db.close()
    return jsonify([{"id": r[0], "name": r[1], "email": r[2], "age": r[3]} for r in rows])


if __name__ == "__main__":
    app.run(debug=True)

