"""Tests for the bulk CSV import endpoint.

Covers: clean import, mixed (some valid / some invalid), all-bad
(zero rows imported), and empty file. Asserts both response JSON and
actual SQLite table contents.
"""

import sqlite3

import pytest

from app import app as flask_app, DATABASE


@pytest.fixture()
def client(tmp_path, monkeypatch):
    monkeypatch.setattr("app.DATABASE", str(tmp_path / "users.db"))
    with flask_app.test_client() as client:
        yield client


def table_contents():
    db = sqlite3.connect(DATABASE)
    try:
        return db.execute(
            "SELECT name, email, age FROM users ORDER BY id"
        ).fetchall()
    finally:
        db.close()


def post_csv(client, text):
    data = {"file": (text.encode("utf-8"), "rows.csv")}
    return client.post("/import", data=data, content_type="multipart/form-data")


HEADER = "name,email,age\n"


class TestCleanImport:
    def test_all_rows_imported(self, client):
        csv_text = HEADER + "Alice,alice@example.com,30\nBob,bob@example.com,25\n"
        resp = post_csv(client, csv_text)

        assert resp.status_code == 200
        assert resp.get_json() == {"imported": 2, "errors": []}
        assert table_contents() == [
            ("Alice", "alice@example.com", 30),
            ("Bob", "bob@example.com", 25),
        ]

    def test_single_row(self, client):
        resp = post_csv(client, HEADER + "Carol,carol@example.com,41\n")
        assert resp.status_code == 200
        assert resp.get_json() == {"imported": 1, "errors": []}
        assert table_contents() == [("Carol", "carol@example.com", 41)]


class TestMixedImport:
    def test_only_valid_rows_inserted(self, client):
        csv_text = (
            HEADER
            + "Alice,alice@example.com,30\n"      # line 2: ok
            + "Bob,bad-email,25\n"                # line 3: bad email
            + "Charlie,charlie@example.com,999\n" # line 4: age out of range
            + "Dana,dana@example.com,-1\n"        # line 5: negative age
            + "Eve,eve@example.com,abc\n"         # line 6: non-integer age
            + ",frank@example.com,50\n"           # line 7: empty name
            + "Grace,grace@example.com,0\n"       # line 8: ok (boundary age)
        )
        resp = post_csv(client, csv_text)

        assert resp.status_code == 200
        body = resp.get_json()
        assert body["imported"] == 2
        assert body["errors"] == [
            {"line": 3, "reason": "invalid email format"},
            {"line": 4, "reason": "age out of range (0-150)"},
            {"line": 5, "reason": "age out of range (0-150)"},
            {"line": 6, "reason": "age is not an integer"},
            {"line": 7, "reason": "name is empty"},
        ]
        assert table_contents() == [
            ("Alice", "alice@example.com", 30),
            ("Grace", "grace@example.com", 0),
        ]


class TestAllBadImport:
    def test_zero_rows_imported(self, client):
        csv_text = (
            HEADER
            + "Bob,bad-email,25\n"
            + "Charlie,charlie@example.com,999\n"
            + "Eve,eve@example.com,abc\n"
        )
        resp = post_csv(client, csv_text)

        assert resp.status_code == 200
        assert resp.get_json() == {
            "imported": 0,
            "errors": [
                {"line": 2, "reason": "invalid email format"},
                {"line": 3, "reason": "age out of range (0-150)"},
                {"line": 4, "reason": "age is not an integer"},
            ],
        }
        assert table_contents() == []


class TestEmptyFile:
    def test_header_only(self, client):
        resp = post_csv(client, HEADER)

        assert resp.status_code == 200
        assert resp.get_json() == {"imported": 0, "errors": []}
        assert table_contents() == []

    def test_completely_empty(self, client):
        resp = post_csv(client, "")

        assert resp.status_code == 200
        assert resp.get_json() == {"imported": 0, "errors": []}
        assert table_contents() == []

